package com.kanjicombat.app;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.content.*;import android.net.Uri;import android.speech.tts.TextToSpeech;import java.util.Locale;import java.io.OutputStream;
public class MainActivity extends Activity {
 WebView web;TextToSpeech tts;boolean ready=false;ValueCallback<Uri[]> chooser;String pendingText;static final int PICK=1,SAVE=2;
 @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);setContentView(web);web.setBackgroundColor(0xff090b10);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setMediaPlaybackRequiresUserGesture(false);s.setAllowFileAccess(true);s.setAllowContentAccess(true);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(!"file".equals(r.getUrl().getScheme())){try{startActivity(new Intent(Intent.ACTION_VIEW,r.getUrl()));}catch(Exception e){}return true;}return false;}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;try{startActivityForResult(p.createIntent(),PICK);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;return false;}return true;}});tts=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS){int result=tts.setLanguage(Locale.JAPAN);ready=result>=0;tts.setSpeechRate(.85f);}});web.addJavascriptInterface(new Bridge(),"AndroidVoice");web.loadUrl("file:///android_asset/index.html");}
 class Bridge {@JavascriptInterface public void speak(String text){runOnUiThread(()->{if(ready)tts.speak(text,TextToSpeech.QUEUE_FLUSH,null,"kc");else android.widget.Toast.makeText(MainActivity.this,"Install Japanese TTS voice in Android settings.",android.widget.Toast.LENGTH_LONG).show();});}
 @JavascriptInterface public void exportText(String name,String content,String type){runOnUiThread(()->{pendingText=content;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(type);i.putExtra(Intent.EXTRA_TITLE,name);startActivityForResult(i,SAVE);});}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK&&chooser!=null){chooser.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(result,data));chooser=null;}if(req==SAVE&&result==RESULT_OK&&data!=null){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(pendingText.getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){android.widget.Toast.makeText(this,"Export failed",0).show();}}}
 @Override protected void onDestroy(){if(tts!=null)tts.shutdown();web.destroy();super.onDestroy();}
}